function report = exportNR5GPublicationResults(integrityFile, outputDir)
%EXPORTNR5GPUBLICATIONRESULTS Springer Nature-ready 5G results from saved MAT.
%   report = exportNR5GPublicationResults(integrityFile, outputDir)
%
% The input is integrity5G_results.mat generated by B_Integrity_5G_Paper.mlx.
% Outputs: self-contained LaTeX booktabs tables, vector PDFs, 600-dpi PNG
% previews, and one CSV with per-epoch evidence. No synthetic data are used.
%
% Notes:
% - Reported exceedance fractions are DESCRIPTIVE, not certified risk.
% - Operational availability is N/A unless both HAL and VAL are defined.
% - The diagonal-covariance model is a deliberately misspecified ablation.
% - No Galileo results are fabricated; these tables are 5G-only.

if nargin < 1 || isempty(integrityFile)
    integrityFile = 'integrity5G_results.mat';
end
if nargin < 2 || isempty(outputDir)
    outputDir = fullfile(fileparts(char(integrityFile)), 'paper_assets', '5g');
end
assert(isfile(integrityFile), 'Missing integrity MAT file: %s', integrityFile);
S = load(integrityFile, 'integrity5G');
assert(isfield(S, 'integrity5G'), 'MAT file has no integrity5G struct.');
d = S.integrity5G;
required = {'tEpoch_s','truthENU','originalPosENU','positionWLS_ENU', ...
    'valid','nUsedGNB','HPL_m','VPL_m','errorHorizontal_m', ...
    'errorVertical_m','errorHorizontalOriginal_m','status'};
for k = 1:numel(required)
    assert(isfield(d, required{k}), 'Missing integrity5G.%s', required{k});
end

n = numel(d.tEpoch_s);
assert(n > 0 && numel(d.valid) == n && size(d.truthENU,1) == n, ...
    'Inconsistent number of 5G epochs.');
valid = logical(d.valid(:));
valid = valid & isfinite(d.HPL_m(:)) & isfinite(d.VPL_m(:)) ...
    & isfinite(d.errorHorizontal_m(:)) & isfinite(d.errorVertical_m(:));
status = d.status(:);
if isstring(status), status = cellstr(status); end
assert(numel(status)==n, 'Status array length must equal nEpochs.');

if ~isfolder(outputDir), mkdir(outputDir); end
outputDir = char(outputDir);
report = struct('outputDir',outputDir,'totalEpochs',n, ...
    'validEpochs',nnz(valid));

% Valid epochs are the denominator of conditional error/PL statistics.
hErr = d.errorHorizontal_m(:);
vErr = d.errorVertical_m(:);
hpl = d.HPL_m(:);
vpl = d.VPL_m(:);
nGN = d.nUsedGNB(:);
t = d.tEpoch_s(:);
origPos = double(d.originalPosENU);
origValid = all(isfinite(origPos),2) & ~all(origPos==0,2);
origError = d.errorHorizontalOriginal_m(:);
origValid = origValid & isfinite(origError);
hExceed = valid & (hErr > hpl);
vExceed = valid & (vErr > vpl);

hasLimits = isfield(d,'HAL_m') && isfield(d,'VAL_m') && ...
    isfinite(d.HAL_m) && isfinite(d.VAL_m);
if hasLimits
    opAvailable = valid & hpl <= d.HAL_m & vpl <= d.VAL_m;
else
    opAvailable = false(n,1);
end

% Categorize failure *diagnostics* without treating them as faults.
reasonFew = ~valid & contains(status,'Too few visible');
reasonObs = ~valid & contains(status,'indices do not match');
reasonInit = ~valid & contains(status,'initial position');
reasonGeom = ~valid & (contains(status,'geometry') | ...
    contains(status,'coincides with a gNB') | contains(status,'Unobservable'));
reasonSolver = ~valid & (contains(status,'converge') | ...
    contains(status,'line search'));
reasonOther = ~valid & ~(reasonFew | reasonObs | reasonInit | ...
    reasonGeom | reasonSolver);

% 1. Table: computability and geometry; rates relative to ALL epochs.
f = openTextFile(fullfile(outputDir,'table_5g_computability.tex'));
cleanup = onCleanup(@() fclose(f));
fprintf(f,'%% MATLAB-generated. Conditional 5G results; no Galileo values.\n');
fprintf(f,'\\begin{table*}[t]\n');
fprintf(f,'\\caption{Epoch-wise computability and geometry of the 5G DL--TDOA WLS solution. All proportions use the total number of simulated epochs as denominator.}\n');
fprintf(f,'\\label{tab:5g-computability}\n\\centering\n');
fprintf(f,'\\begin{tabular}{@{}lrr@{}}\n\\toprule\n');
printRow(f,{'Metric','Epochs','Proportion'});
fprintf(f,'\\midrule\n');
addCountRow(f,'Simulated epochs',n,n);
addCountRow(f,'Valid 3D WLS and PL',nnz(valid),n);
addCountRow(f,'Fewer than four visible gNBs',nnz(nGN<4),n);
addCountRow(f,'Exactly four visible gNBs (no TDOA redundancy)',nnz(nGN==4),n);
addCountRow(f,'Five or more visible gNBs',nnz(nGN>=5),n);
addCountRow(f,'Observation-set mismatch',nnz(reasonObs),n);
addCountRow(f,'Initialization failures',nnz(reasonInit),n);
addCountRow(f,'Geometry failures',nnz(reasonGeom),n);
addCountRow(f,'Solver failures',nnz(reasonSolver),n);
addCountRow(f,'Other invalid epochs',nnz(reasonOther),n);
if hasLimits
    addCountRow(f,'$HPL\leq HAL$ and $VPL\leq VAL$',nnz(opAvailable),n);
else
    printRow(f,{'Operational availability (HAL/VAL undefined)','N/A','N/A'});
end
fprintf(f,'\\bottomrule\n\\end{tabular}\n\\end{table*}\n');
clear cleanup

% 2. Table: 5G accuracy, PL distribution and descriptive exceedances.
f = openTextFile(fullfile(outputDir,'table_5g_performance.tex'));
cleanup = onCleanup(@() fclose(f));
fprintf(f,'%% MATLAB-generated. Valid-epoch denominators only.\n');
fprintf(f,'\\begin{table}[t]\n');
fprintf(f,'\\caption{Horizontal/vertical accuracy and model-conditional protection levels for valid 5G DL--TDOA WLS epochs. The exceedance counts are empirical diagnostics, not integrity-risk estimates.}\n');
fprintf(f,'\\label{tab:5g-performance}\n\\centering\n');
fprintf(f,'\\begin{tabular}{@{}lr@{}}\n\\toprule\n');
printRow(f,{'Metric','5G WLS'});
fprintf(f,'\\midrule\n');
printRow(f,{'Valid epochs',sprintf('%d',nnz(valid))});
printRow(f,{'Horizontal RMSE (m)',fmtNum(rmseFinite(hErr(valid)))});
printRow(f,{'Vertical RMSE (m)',fmtNum(rmseFinite(vErr(valid)))});
printRow(f,{'Horizontal error P95 (m)',fmtNum(percentileFinite(hErr(valid),95))});
printRow(f,{'Vertical error P95 (m)',fmtNum(percentileFinite(vErr(valid),95))});
printRow(f,{'Median HPL (m)',fmtNum(percentileFinite(hpl(valid),50))});
printRow(f,{'HPL P95 (m)',fmtNum(percentileFinite(hpl(valid),95))});
printRow(f,{'Median VPL (m)',fmtNum(percentileFinite(vpl(valid),50))});
printRow(f,{'VPL P95 (m)',fmtNum(percentileFinite(vpl(valid),95))});
printRow(f,{'Horizontal PL exceedances',sprintf('%d / %d',nnz(hExceed),nnz(valid))});
printRow(f,{'Vertical PL exceedances',sprintf('%d / %d',nnz(vExceed),nnz(valid))});
fprintf(f,'\\bottomrule\n\\end{tabular}\n\\end{table}\n');
clear cleanup

% 3. Covariance-model ablation computed over IDENTICAL matched epochs.
hasDiag = isfield(d,'validDiagonal') && isfield(d,'HPL_diagonal_m') ...
    && isfield(d,'errorHorizontalDiagonal_m');
if hasDiag
    vd = logical(d.validDiagonal(:)) & isfinite(d.HPL_diagonal_m(:)) ...
        & isfinite(d.errorHorizontalDiagonal_m(:));
    matched = valid & vd;
    hd = d.errorHorizontalDiagonal_m(:);
    hpld = d.HPL_diagonal_m(:);
else
    vd = false(n,1); matched = false(n,1);
    hd = nan(n,1); hpld = nan(n,1);
end
paired = matched;                   % Two WLS fits on common epochs.
matched = paired & origValid;        % Three estimators on identical epochs.

f = openTextFile(fullfile(outputDir,'table_5g_covariance_ablation.tex'));
cleanup = onCleanup(@() fclose(f));
fprintf(f,'%% Original estimator has no HPL; diagonal covariance is deliberately misspecified.\n');
fprintf(f,'\\begin{table*}[t]\n');
fprintf(f,'\\caption{TDOA covariance-model ablation over epochs valid for all three methods ($n=%d$). The diagonal model neglects reference-induced correlation and is used only as a sensitivity experiment.}\n', ...
    nnz(matched));
fprintf(f,'\\label{tab:5g-cov-ablation}\n\\centering\n');
fprintf(f,'\\begin{tabular}{@{}lccc@{}}\n\\toprule\n');
printRow(f,{'Method','H-RMSE (m)','Median HPL (m)','HPL violations'});
fprintf(f,'\\midrule\n');
printRow(f,{'Original 5G estimator',fmtNum(rmseFinite(origError(matched))),'N/A','N/A'});
printRow(f,{'WLS with full $\mat{R}$',fmtNum(rmseFinite(hErr(matched))), ...
    fmtNum(percentileFinite(hpl(matched),50)), ...
    fmtCountRatio(nnz(matched & hErr>hpl),nnz(matched))});
printRow(f,{'WLS with diagonal $\mat{R}$',fmtNum(rmseFinite(hd(matched))), ...
    fmtNum(percentileFinite(hpld(matched),50)), ...
    fmtCountRatio(nnz(matched & hd>hpld),nnz(matched))});
fprintf(f,'\\bottomrule\n\\end{tabular}\n\\end{table*}\n');
clear cleanup

% Export one observation per epoch, preserving invalid epochs and NaNs.
if isfield(d,'conditionWhiteG'), condWhite = d.conditionWhiteG(:);
else, condWhite = nan(n,1); end
if isfield(d,'referenceGNB'), refId = d.referenceGNB(:);
else, refId = nan(n,1); end
epochData = table((1:n).',t,valid,nGN,refId,hErr,vErr,hpl,vpl, ...
    origError,vd,hd,hpld,condWhite,string(status), ...
    'VariableNames',{'epoch','time_s','validWLS','visibleGNBs', ...
    'referenceGNB','horizontalError_m','verticalError_m', ...
    'HPL_m','VPL_m','horizontalErrorOriginal_m', ...
    'validDiagonalWLS','horizontalErrorDiagonal_m', ...
    'HPLDiagonal_m','whitenedGeometryCondition','status'});
writetable(epochData,fullfile(outputDir,'5g_epoch_metrics.csv'));

% Consistent publication styling: no figure titles or embedded captions.
% Cite/describe the figure in LaTeX, not inside the graphics.
if nnz(valid)>0
    fig = newFigure(17.0,7.2);
    ax = axes(fig); hold(ax,'on');
    plot(ax,t,hErr,'-','Color',[.1 .1 .1],'LineWidth',1.0,'DisplayName','Horizontal error');
    plot(ax,t,hpl,'--','Color',[.08 .36 .62],'LineWidth',1.25,'DisplayName','HPL');
    if hasLimits
        yline(ax,d.HAL_m,':','Color',[.55 .2 .2],'LineWidth',1, ...
            'DisplayName','HAL');
    end
    if any(hExceed)
        plot(ax,t(hExceed),hErr(hExceed),'x','Color',[.75 .18 .15], ...
            'MarkerSize',5,'LineWidth',1,'DisplayName','HPL exceedance');
    end
    setAxis(ax,'Time (s)','Horizontal error / bound (m)');
    legend(ax,'Location','best','Box','off');
    saveFigure(fig,outputDir,'fig_5g_horizontal');

    fig = newFigure(17.0,7.2);
    ax = axes(fig); hold(ax,'on');
    plot(ax,t,vErr,'-','Color',[.1 .1 .1],'LineWidth',1.0,'DisplayName','Absolute vertical error');
    plot(ax,t,vpl,'--','Color',[.08 .36 .62],'LineWidth',1.25,'DisplayName','VPL');
    if hasLimits
        yline(ax,d.VAL_m,':','Color',[.55 .2 .2],'LineWidth',1, ...
            'DisplayName','VAL');
    end
    if any(vExceed)
        plot(ax,t(vExceed),vErr(vExceed),'x','Color',[.75 .18 .15], ...
            'MarkerSize',5,'LineWidth',1,'DisplayName','VPL exceedance');
    end
    setAxis(ax,'Time (s)','Vertical error / bound (m)');
    legend(ax,'Location','best','Box','off');
    saveFigure(fig,outputDir,'fig_5g_vertical');

    fig = newFigure(17.0,10.2);
    tl = tiledlayout(fig,2,1,'TileSpacing','compact','Padding','compact');
    ax = nexttile(tl);
    plot(ax,t,nGN,'-','Color',[.08 .36 .62],'LineWidth',1.0);
    yline(ax,4,'--','Color',[.35 .35 .35],'LineWidth',0.8);
    setAxis(ax,'','Visible gNB count');
    ax = nexttile(tl);
    goodCond = condWhite;
    goodCond(~valid | ~isfinite(goodCond) | goodCond<=0) = NaN;
    semilogy(ax,t,goodCond,'-','Color',[.1 .1 .1],'LineWidth',1.0);
    setAxis(ax,'Time (s)','cond($R^{-1/2}G$)');
    ax.YLabel.Interpreter = 'latex';
    saveFigure(fig,outputDir,'fig_5g_geometry');

    fig = newFigure(8.5,8.5);
    ax = axes(fig); hold(ax,'on');
    scatter(ax,hpl(valid),hErr(valid),10,[.12 .35 .56],'filled');
    lim = max([hpl(valid);hErr(valid)]);
    lim = max(lim,1);
    plot(ax,[0 lim],[0 lim],'--','Color',[.25 .25 .25],'LineWidth',0.9);
    xlim(ax,[0 lim]); ylim(ax,[0 lim]); axis(ax,'square');
    setAxis(ax,'HPL (m)','Horizontal position error (m)');
    saveFigure(fig,outputDir,'fig_5g_error_vs_hpl');
end

if nnz(paired)>0
    f = newFigure(17.0,9.6);
    tl = tiledlayout(f,2,1,'TileSpacing','compact','Padding','compact');
    a = nexttile(tl); hold(a,'on');
    pf = hpl; pf(~paired) = NaN;
    pd = hpld; pd(~paired) = NaN;
    plot(a,t,pf,'-','Color',[.08 .36 .62],'LineWidth',1.15, ...
        'DisplayName','Full correlated R');
    plot(a,t,pd,'--','Color',[.6 .2 .16],'LineWidth',1.15, ...
        'DisplayName','Diagonal R (misspecified)');
    setAxis(a,'','HPL (m)'); legend(a,'Location','best','Box','off');
    a = nexttile(tl); hold(a,'on');
    ef = hErr; ef(~paired) = NaN;
    ed = hd; ed(~paired) = NaN;
    plot(a,t,ef,'-','Color',[.08 .36 .62],'LineWidth',1.0, ...
        'DisplayName','Full correlated R');
    plot(a,t,ed,'--','Color',[.6 .2 .16],'LineWidth',1.0, ...
        'DisplayName','Diagonal R (misspecified)');
    setAxis(a,'Time (s)','Horizontal error (m)');
    legend(a,'Location','best','Box','off');
    saveFigure(f,outputDir,'fig_5g_covariance_ablation');
end

% Document modeling choices. CSV and LaTeX are data artifacts, not risk proof.
f = openTextFile(fullfile(outputDir,'publication_manifest.txt'));
cleanup = onCleanup(@() fclose(f));
fprintf(f,'5G DL-TDOA conditional integrity: publication outputs\n');
fprintf(f,'Source MAT: %s\n',char(integrityFile));
fprintf(f,'Generated by: exportNR5GPublicationResults.m\n');
fprintf(f,'Simulation epochs: %d\nValid WLS epochs: %d\n',n,nnz(valid));
fprintf(f,'Matched three-method ablation epochs: %d\n',nnz(matched));
if isfield(d,'sigmaTOA_ns'), fprintf(f,'Assumed TOA sigma (ns): %.9g\n',d.sigmaTOA_ns); end
if isfield(d,'syncBiasBound_ns'), fprintf(f,'Sync bound (ns): %.9g\n',d.syncBiasBound_ns); end
if isfield(d,'nlosBiasBound_ns'), fprintf(f,'NLOS bound (ns): %.9g\n',d.nlosBiasBound_ns); end
if isfield(d,'pH'), fprintf(f,'Conditional horizontal tail alpha: %.9g\n',d.pH); end
if isfield(d,'pV'), fprintf(f,'Conditional vertical tail alpha: %.9g\n',d.pV); end
if hasLimits
    fprintf(f,'HAL (m): %.9g\nVAL (m): %.9g\n',d.HAL_m,d.VAL_m);
else
    fprintf(f,'HAL/VAL: not set; operational availability undefined\n');
end
fprintf(f,['HPL/VPL are local Gaussian plus configured bounded-bias model values.\n' ...
    'Empirical exceedance counts are diagnostics, not rare-event risk validation.\n' ...
    'Potentially correlated epochs must not be considered independent trials.\n' ...
    'The diagonal-R ablation is intentionally statistically misspecified.\n' ...
    'PDF figures are vector graphics; PNG previews are rasterized at 600 dpi.\n']);
clear cleanup

report.files = {'table_5g_computability.tex','table_5g_performance.tex', ...
    'table_5g_covariance_ablation.tex','5g_epoch_metrics.csv', ...
    'publication_manifest.txt'};
report.matchedAblationEpochs = nnz(matched);
report.horizontalExceedances = nnz(hExceed);
report.verticalExceedances = nnz(vExceed);
fprintf('Springer Nature 5G publication outputs: %s\n',outputDir);
end

function f = newFigure(widthCm,heightCm)
f = figure('Visible','off','Color','white','Units','centimeters', ...
    'Position',[2 2 widthCm heightCm],'Renderer','painters');
set(f,'PaperPositionMode','auto','InvertHardcopy','off');
end

function setAxis(ax,xLab,yLab)
set(ax,'FontName','Arial','FontSize',8,'LineWidth',0.7,'Box','off', ...
    'TickDir','out','Color','white');
grid(ax,'on'); ax.GridAlpha = 0.14;
if ~isempty(xLab), xlabel(ax,xLab,'FontName','Arial','FontSize',9); end
if ~isempty(yLab), ylabel(ax,yLab,'FontName','Arial','FontSize',9); end
end

function saveFigure(f,outDir,baseName)
pdfPath = fullfile(outDir,[baseName '.pdf']);
pngPath = fullfile(outDir,[baseName '.png']);
try
    exportgraphics(f,pdfPath,'ContentType','vector','BackgroundColor','white');
catch err
    warning('Vector exportgraphics unavailable (%s); using print -painters.',err.message);
    print(f,pdfPath,'-dpdf','-painters');
end
exportgraphics(f,pngPath,'Resolution',600,'BackgroundColor','white');
close(f);
end

function f = openTextFile(filename)
[f,msg] = fopen(filename,'w');
assert(f>0,'Cannot write %s: %s',filename,msg);
end

function printRow(f,items)
% '\\\\' is two literal LaTeX backslashes after fprintf unescapes it.
fprintf(f,'%s \\\\\n',strjoin(items,' & '));
end

function addCountRow(f,label,count,total)
printRow(f,{label,sprintf('%d',count),pctText(count,total)});
end

function s = pctText(count,total)
if total==0, s='N/A';
else, s=sprintf('%.1f\\%%',100*count/total);
end
end

function s = fmtCountRatio(a,b)
if b==0, s='N/A';
else, s=sprintf('%d / %d',a,b);
end
end

function v = rmseFinite(x)
x = x(isfinite(x));
if isempty(x), v=NaN;
else, v=sqrt(mean(x.^2));
end
end

function v = percentileFinite(x,p)
% Deterministic linear interpolation; does not require Statistics Toolbox.
x = sort(x(isfinite(x)));
if isempty(x), v=NaN; return; end
if numel(x)==1, v=x(1); return; end
idx = 1 + (numel(x)-1)*p/100;
lo = floor(idx); hi = ceil(idx);
v = x(lo) + (idx-lo)*(x(hi)-x(lo));
end

function s = fmtNum(x)
if ~isfinite(x), s='N/A';
else, s=sprintf('%.3f',x);
end
end
